#!/usr/bin/env node
/**
 * Copies third-party browser libraries from node_modules into assets/vendor/.
 *
 * WordPress.org does not allow loading scripts from CDNs, so libraries ship
 * with the plugin. Bare import specifiers ("three",
 * "@photo-sphere-viewer/core") are rewritten to SlashPhoto-prefixed module
 * IDs, which the plugin registers in WordPress' import map. That keeps our
 * copies from colliding with another plugin that registers "three" in a
 * different version.
 *
 * Each library goes into a versioned folder, so browser caches never mix
 * versions, and a manifest.php tells the PHP side where everything is.
 *
 * Usage: npm run vendor
 */

import { copyFileSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join( dirname( fileURLToPath( import.meta.url ) ), '..' );
const modules = join( root, 'node_modules' );
const out = join( root, 'assets', 'vendor' );

/** Bare specifier => SlashPhoto module ID. */
const SPECIFIERS = {
	three: '@slashphoto/vendor/three',
	'@photo-sphere-viewer/core': '@slashphoto/vendor/psv-core',
	'@photo-sphere-viewer/visible-range-plugin': '@slashphoto/vendor/psv-visible-range',
};

/**
 * id: module ID; files: [source in package, target name]; module: entry file
 * registered as a script module; deps: module IDs it imports.
 */
const LIBRARIES = [
	{
		pkg: 'three',
		id: '@slashphoto/vendor/three',
		files: [
			[ 'build/three.module.min.js', 'three.module.min.js' ],
			[ 'build/three.core.min.js', 'three.core.min.js' ],
			[ 'LICENSE', 'LICENSE' ],
		],
		module: 'three.module.min.js',
		deps: [],
	},
	{
		pkg: '@photo-sphere-viewer/core',
		id: '@slashphoto/vendor/psv-core',
		files: [
			[ 'index.module.js', 'index.module.js' ],
			[ 'index.css', 'index.css' ],
			[ 'LICENSE', 'LICENSE' ],
		],
		module: 'index.module.js',
		style: 'index.css',
		deps: [ '@slashphoto/vendor/three' ],
	},
	{
		pkg: '@photo-sphere-viewer/visible-range-plugin',
		id: '@slashphoto/vendor/psv-visible-range',
		files: [
			[ 'index.module.js', 'index.module.js' ],
			[ 'LICENSE', 'LICENSE' ],
		],
		module: 'index.module.js',
		deps: [ '@slashphoto/vendor/three', '@slashphoto/vendor/psv-core' ],
	},
];

function rewriteSpecifiers( code ) {
	return code.replace( /(\bfrom\s*|\bimport\s*\(?\s*)(["'])([^"']+)\2/g, ( match, prefix, quote, spec ) =>
		SPECIFIERS[ spec ] ? `${ prefix }${ quote }${ SPECIFIERS[ spec ] }${ quote }` : match
	);
}

rmSync( out, { recursive: true, force: true } );
mkdirSync( out, { recursive: true } );

const manifest = {};
for ( const lib of LIBRARIES ) {
	const pkgDir = join( modules, lib.pkg );
	const { version, license } = JSON.parse( readFileSync( join( pkgDir, 'package.json' ), 'utf8' ) );
	const folder = `${ lib.pkg.replace( /^@/, '' ).replace( /\//g, '-' ) }-${ version }`;
	const target = join( out, folder );
	mkdirSync( target, { recursive: true } );

	for ( const [ from, to ] of lib.files ) {
		const src = join( pkgDir, from );
		if ( to.endsWith( '.js' ) ) {
			// Drop source map references; the maps are not shipped.
			const code = rewriteSpecifiers( readFileSync( src, 'utf8' ) ).replace( /\n?\/\/# sourceMappingURL=\S+\s*$/, '\n' );
			writeFileSync( join( target, to ), code );
		} else {
			copyFileSync( src, join( target, to ) );
		}
	}

	manifest[ lib.id ] = {
		package: lib.pkg,
		version,
		license,
		module: `${ folder }/${ lib.module }`,
		style: lib.style ? `${ folder }/${ lib.style }` : null,
		deps: lib.deps,
	};
	console.log( `${ lib.pkg }@${ version } (${ license }) -> assets/vendor/${ folder }` );
}

const php = [
	'<?php',
	'/**',
	' * Generated by bin/vendor.mjs (npm run vendor). Do not edit.',
	' *',
	' * @package SlashPhoto',
	' */',
	'',
	"defined( 'ABSPATH' ) || exit;",
	'',
	'return ' + toPhp( manifest, 0 ) + ';',
	'',
].join( '\n' );
writeFileSync( join( out, 'manifest.php' ), php );

function toPhp( value, depth ) {
	const pad = '\t'.repeat( depth + 1 );
	const end = '\t'.repeat( depth );
	if ( value === null ) {
		return 'null';
	}
	if ( Array.isArray( value ) ) {
		return value.length ? `[\n${ value.map( ( v ) => pad + toPhp( v, depth + 1 ) ).join( ',\n' ) },\n${ end }]` : '[]';
	}
	if ( typeof value === 'object' ) {
		const keys = Object.keys( value );
		const width = Math.max( ...keys.map( ( k ) => k.length + 2 ) );
		return `[\n${ keys
			.map( ( k ) => `${ pad }${ `'${ k }'`.padEnd( width ) } => ${ toPhp( value[ k ], depth + 1 ) }` )
			.join( ',\n' ) },\n${ end }]`;
	}
	return `'${ String( value ).replace( /\\/g, '\\\\' ).replace( /'/g, "\\'" ) }'`;
}
